// Guardrail Ebene 2: Thema und Fragen kurz halten, leere Eingabe abweisen, harte Obergrenze je Auftrag (10.11.2026).
// Warum Zaehler im Sub: das Werkzeug kostet Geld (Sonar ueber den Schluessel). Der Prompt erlaubt 1 Aufruf, ein Modell haelt sich nicht sicher daran (Lauf 2564: 4 statt 1).
// Der Zaehler steht in den Workflow-Daten (Static Data), Schluessel ist die trace_id des Hauptlaufs. Er zaehlt jeden gueltigen Aufruf, auch einen fehlgeschlagenen.
const j = $input.first().json;
const MAX_AUFRUFE = 2; // 1 Recherche plus 1 Wiederholung nach FEHLER; jeder weitere Aufruf bekommt FEHLER ohne Sonar
const thema = String(j.thema ?? '').trim().slice(0, 300);
const fragen = String(j.fragen ?? '').trim().slice(0, 600);
const trace = String(j.trace_id ?? '').trim().slice(0, 60) || 'ohne_trace_id';
const sd = $getWorkflowStaticData('global');
if (!sd.recherche_zaehler || typeof sd.recherche_zaehler !== 'object') sd.recherche_zaehler = {};
const jetzt = Date.now();
// alte Eintraege nach 6 Stunden entfernen, damit die Tabelle nicht waechst
for (const k of Object.keys(sd.recherche_zaehler)) { if (jetzt - (sd.recherche_zaehler[k].zeit || 0) > 6 * 3600 * 1000) delete sd.recherche_zaehler[k]; }
let fehler = '';
let nr = 0;
if (thema.length < 3) {
  fehler = 'FEHLER: Thema fehlt oder ist zu kurz, Recherche nicht ausgeführt.';
} else {
  const z = sd.recherche_zaehler[trace] || { n: 0, zeit: jetzt };
  z.n += 1; z.zeit = jetzt;
  sd.recherche_zaehler[trace] = z;
  nr = z.n;
  if (z.n > MAX_AUFRUFE) fehler = 'FEHLER: Grenze für Recherchen in diesem Auftrag erreicht (höchstens ' + MAX_AUFRUFE + '), keine weitere Recherche.';
}
return [{ json: { thema: thema, fragen: fragen, trace_id: trace, aufruf_nr: nr, eingabe_ok: fehler === '', fehler_text: fehler } }];

// Rückgabe an den Agenten: Fakten mit Quelle, Kosten aus usage.cost, feste Nicht-Treffer-Werte
// v02 (10.11.2026): nur Fakten, deren Link-Host in den echten Suchtreffern der Antwort steht (citations, annotations); Zeilen auf 400 Zeichen begrenzt.
// v03.1 (10.11.2026): Links werden bei der Kuerzung auf 400 Zeichen nicht mehr durchgeschnitten.
// v03 (10.11.2026): Sonar schreibt Quellen oft als Fußnote [n] statt als Link (Lauf 2601: 5 belegte Zeilen, 14 Suchtreffer, trotzdem NICHT_GEFUNDEN, bezahlt). Die Fußnote [n] zeigt auf den n-ten Suchtreffer (citations, sonst annotations); die Zeile bekommt den Link dieses Treffers. Eine Fußnote ohne Suchtreffer bleibt unbelegt und wird verworfen.
const r = $input.first().json || {};
if (r.error) {
  const m = (r.error && (r.error.message || r.error)) || 'unbekannt';
  return [{ json: { antwort: 'FEHLER: Recherche nicht erreichbar (' + String(m).slice(0, 160) + ').', kosten_usd: null } }];
}
const msg = (((r.choices || [])[0] || {}).message) || {};
const text = String(msg.content || '').trim();
const kosten = (r.usage && typeof r.usage.cost === 'number') ? r.usage.cost : null;
const tokens = r.usage ? (r.usage.total_tokens || null) : null;
// echte Quellen: Suchtreffer der Antwort in ihrer Reihenfolge, nicht der Text des Modells
const cit = (Array.isArray(r.citations) ? r.citations : []).filter(c => typeof c === 'string');
const ann = (Array.isArray(msg.annotations) ? msg.annotations : []).map(a => a && ((a.url_citation && a.url_citation.url) || a.url)).filter(u => typeof u === 'string');
const treffer = cit.length > 0 ? cit : ann;
const urls = cit.concat(ann);
const host = u => String(u).replace(/^https?:\/\/(www\.)?/i, '').split(/[\/?#]/)[0].toLowerCase();
const hosts = new Set(urls.map(host).filter(Boolean));
const kuerzen = s => (s.length > 400 ? s.slice(0, 399).trimEnd() + '…' : s);
// Zeilen mit Link: gekuerzt wird der Text vor "(Quelle: ...)", nie der Link (Lauf 2617: Links wurden bei 400 Zeichen mitten in der Adresse abgeschnitten)
const kuerzenMitLink = z => {
  if (z.length <= 400) return z;
  const m = z.match(/\s*\((?:Quelle|Quellen):/i);
  if (m && m.index > 0) { const tail = z.slice(m.index); if (tail.length <= 360) return z.slice(0, 400 - tail.length - 1).trimEnd() + '…' + tail; }
  return kuerzen(z);
};
const zeilen0 = text.split('\n').map(z => z.trim()).filter(z => z.startsWith('-'));
const FUSS = /\[(\d{1,2})\]/g;
let vorher = 0;
const fakten = [];
for (const z of zeilen0) {
  if (/https?:\/\//.test(z)) {
    // Zeile mit Link: nur behalten, wenn der Host in den Suchtreffern steht (ohne Suchtreffer bleibt die Link-Prüfung des Modells)
    vorher += 1;
    if (hosts.size > 0 && !(z.match(/https?:\/\/[^\s)\],]+/g) || []).some(u => hosts.has(host(u)))) continue;
    fakten.push(kuerzenMitLink(z));
    continue;
  }
  const nummern = Array.from(z.matchAll(FUSS)).map(m => parseInt(m[1], 10));
  if (nummern.length === 0) continue; // weder Link noch Fußnote: unbelegt
  vorher += 1;
  const quellen = [];
  let alleGefunden = true;
  for (const n of nummern) { const u = treffer[n - 1]; if (typeof u !== 'string') alleGefunden = false; else if (!quellen.includes(u)) quellen.push(u); }
  if (!alleGefunden || quellen.length === 0) continue; // eine Fußnote ohne Suchtreffer: die Zeile gilt als unbelegt
  const nutz = quellen.slice(0, 2);
  const suffix = ' (Quelle: ' + nutz.join('; ') + ')';
  if (suffix.length > 350) continue; // Link zu lang, um die Zeile sinnvoll zu kürzen
  let koerper = z.replace(FUSS, '').replace(/\s+([.,;:])/g, '$1').replace(/\s{2,}/g, ' ').trim();
  if (koerper.length + suffix.length > 400) koerper = koerper.slice(0, 400 - suffix.length - 1).trimEnd() + '…';
  fakten.push(koerper + suffix);
}
if (!text || /KEINE_BELEGE/.test(text) || fakten.length === 0) {
  return [{ json: { antwort: 'NICHT_GEFUNDEN: Keine belegten Fakten zu diesem Thema gefunden.', kosten_usd: kosten, tokens: tokens, quellen_treffer: hosts.size, fakten_verworfen: vorher } }];
}
const zeilen = ['STATUS: OK', 'Fakten mit Quelle (nur diese verwenden):'].concat(fakten.slice(0, 5));
return [{ json: { antwort: zeilen.join('\n'), kosten_usd: kosten, tokens: tokens, quellen_treffer: hosts.size, fakten_verworfen: vorher - fakten.length } }];
